<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {api,req} from '../api'
import {state,toast} from '../store'
import ReviewEntry from '../components/ReviewEntry.vue'
import Modal from '../components/Modal.vue'
type Row={check_error:string;campaign_id:number;dyn_id:string;title:string;reward:string;up_name:string;outcome:string;share_id:string;link_state:string;choices:Record<string,string>;evidence:string;checked_at:string;protected:boolean;cleaned:boolean}
type Ledger={items:Row[];total:number;all_total:number;outcomes:Record<string,number>;links:Record<string,number>;cleanup:Record<string,number>;scan:{pages?:number;scanned?:number;cursor?:string;finished?:boolean}}
const data=ref<Ledger>(),busy=ref(''),query=ref(''),outcome=ref(''),link=ref(''),page=ref(0),error=ref('')
const discarded=ref<Record<string,any>[]>([]),discardOpen=ref(false)
async function showDiscarded(){try{discarded.value=(await req<{items:Record<string,any>[]}>('/api/results/discarded')).items;discardOpen.value=true}catch(e){toast(String(e),'danger')}}
async function discardRow(cid:number){busy.value='discard';try{const r=await req<{note:string;state:string}>(`/api/results/${cid}/discard`,{method:'POST',body:JSON.stringify({account_id:owner.value})});toast(r.note,r.state==='done'?'ok':'warn');await load();if(discardOpen.value)await showDiscarded()}catch(e){toast(String(e),'danger')}finally{busy.value=''}}
const history=ref<Record<string,string>[]>([]),historyOpen=ref(false),historyPage=ref(0),chosen=ref<Row>(),selected=ref('')
const owner=computed(()=>state.overview?.accounts.find(a=>a.current)?.id||0)
const outcomes:Record<string,string>={pending:'待开奖',unknown:'待确认',won:'中奖',lost:'未中奖',void:'作废'}
const links:Record<string,string>={verified:'已核对',candidate:'待核对',conflict:'多条候选',missing:'本次未找到',unscanned:'未扫描'}
let generation=0,alive=true,poll:ReturnType<typeof setInterval>|undefined
async function load(){const request=++generation;try{const r=await req<Ledger>(`/api/results?query=${encodeURIComponent(query.value)}&outcome=${outcome.value}&link=${link.value}&offset=${page.value*50}`);if(alive&&request===generation){data.value=r;error.value=''}}catch(e){if(alive&&request===generation)error.value=String(e)}}
function filter(){page.value=0;void load()}
async function settle(){busy.value='settle';try{const r=await api.settle(true,30);toast(`核验 ${r.checked} 条，更新 ${r.decided} 条`,r.problems.length?'warn':'ok');await load();if(r.problems.length)error.value=r.problems.join('；')}catch(e){toast(String(e),'danger')}finally{busy.value=''}}
async function match(resume=false){busy.value='match';try{await req('/api/results/match',{method:'POST',body:JSON.stringify({account_id:owner.value,resume})});await load();toast('转发匹配已更新','ok')}catch(e){toast(String(e),'danger')}finally{busy.value=''}}
async function showHistory(delta=0){historyPage.value=Math.max(0,historyPage.value+delta);try{history.value=(await req<{items:Record<string,string>[]}>(`/api/results/history?offset=${historyPage.value*50}`)).items;historyOpen.value=true}catch(e){toast(String(e),'danger')}}
async function saveLink(){if(!chosen.value||!selected.value)return;busy.value='link';try{await req(`/api/results/${chosen.value.campaign_id}/link`,{method:'PUT',body:JSON.stringify({account_id:owner.value,share_id:selected.value})});chosen.value=undefined;await load()}catch(e){toast(String(e),'danger')}finally{busy.value=''}}
function choose(row:Row){chosen.value=row;selected.value=Object.keys(row.choices)[0]||''}
onMounted(()=>{void load();poll=setInterval(()=>{if(!busy.value)void load()},30000)})
onUnmounted(()=>{alive=false;if(poll)clearInterval(poll)})
</script>
<template><div class="results-workspace">
 <section class="panel result-heading"><div><h2>开奖核验</h2><span class="muted">{{data?.all_total||0}} 条参与记录</span></div><div class="toolbar"><button @click="showDiscarded">移除记录</button><button :disabled="!!busy" @click="load">刷新</button><button :disabled="!!busy" @click="match(false)">{{busy==='match'?'匹配中…':'匹配本人转发'}}</button><button :disabled="!!busy||!data?.scan.cursor" @click="match(true)">继续匹配</button><button class="primary" :disabled="!!busy" @click="settle">{{busy==='settle'?'核验中…':'核验开奖'}}</button></div></section>
 <p v-if="error" class="warning" role="alert">{{error}}</p>
 <div class="result-metrics"><button v-for="(label,key) in outcomes" :key="key" class="panel result-metric" :class="['result-'+key,{selected:outcome===key}]" @click="outcome=outcome===key?'':key;filter()"><span>{{label}}</span><strong>{{data?.outcomes[key]||0}}</strong></button><button class="panel result-metric result-history" @click="historyPage=0;showHistory()"><span>清理历史 ↗</span><strong>{{data?.cleanup.drop_share||0}}<small> 删转发</small></strong><span>{{data?.cleanup.unfollow||0}} 取关</span></button></div>
 <section class="panel result-list"><div class="result-filters"><div class="toolbar"><button class="mini" :class="{on:!link}" @click="link='';filter()">全部关联</button><button v-for="(label,key) in links" :key="key" class="mini" :class="{on:link===key}" @click="link=link===key?'':key;filter()">{{label}} {{data?.links[key]||0}}</button></div><form class="toolbar" @submit.prevent="filter"><input class="ipt" v-model="query" placeholder="活动奖品、UP 或动态号"/><select class="ipt" v-model="outcome" @change="filter"><option value="">全部结果</option><option v-for="(label,key) in outcomes" :value="key" :key="key">{{label}}</option></select><button>搜索</button><span v-if="data?.scan.pages" class="muted scan-status" :title="`已扫描 ${data.scan.pages} 页 · ${data.scan.scanned} 条`">{{data.scan.pages}} 页 / {{data.scan.scanned}} 条</span></form></div>
 <div class="table-scroll"><table class="dense w-full"><thead><tr><th>活动奖品</th><th>开奖状态</th><th>本人转发</th><th>核验依据</th><th>操作</th></tr></thead><tbody><tr v-for="row in data?.items||[]" :key="row.campaign_id"><td><a :href="'https://t.bilibili.com/'+row.dyn_id" target="_blank" rel="noreferrer">{{row.reward||'奖品待补全'}}</a><small>{{row.up_name}}<span v-if="row.cleaned"> · 已清理</span><span v-if="row.protected"> · 已保留</span></small></td><td><span class="chip" :class="row.outcome==='won'?'chip-ok':row.outcome==='unknown'?'chip-warn':''">{{outcomes[row.outcome]||'待确认'}}</span></td><td><span>{{links[row.link_state]}}</span><a v-if="row.share_id" class="share-link" :href="'https://t.bilibili.com/'+row.share_id" target="_blank" rel="noreferrer">查看转发 ↗</a></td><td class="evidence"><span class="evidence-text" :title="row.evidence">{{row.check_error||row.evidence||'—'}}</span><small v-if="row.checked_at">{{new Date(row.checked_at).toLocaleDateString('zh-CN')}}</small></td><td><div class="row-actions"><button v-if="Object.keys(row.choices).length" class="mini" @click="choose(row)">核对关联</button><button v-if="row.check_error==='缺少 UP 信息'" class="mini danger" :disabled="!!busy" @click="discardRow(row.campaign_id)">移除并删转发</button><ReviewEntry :dynamic="row.dyn_id" @saved="load"/></div></td></tr></tbody></table></div>
 <p v-if="!data?.items.length" class="empty-state">暂无记录</p><footer><span>{{data?.total||0}} 条</span><button :disabled="!page" @click="page--;load()">上一页</button><span>{{page+1}} / {{Math.max(1,Math.ceil((data?.total||0)/50))}}</span><button :disabled="(page+1)*50>=(data?.total||0)" @click="page++;load()">下一页</button></footer></section>
 <Modal v-if="discardOpen" title="核验失效项 · 移除记录" wide @close="discardOpen=false"><div class="table-scroll"><table class="dense w-full discard-table"><thead><tr><th>活动奖品</th><th>转发处理</th><th>操作</th></tr></thead><tbody><tr v-for="r in discarded" :key="r.campaign_id"><td>{{r.reward}}</td><td>{{r.note}}</td><td><button v-if="r.state!=='done'" :disabled="!!busy" @click="discardRow(r.campaign_id)">重查转发</button><span v-else class="chip chip-ok">已完成</span></td></tr></tbody></table></div><p v-if="!discarded.length" class="empty-state">暂无移除记录</p></Modal>
 <Modal v-if="historyOpen" title="清理历史" wide @close="historyOpen=false"><div class="table-scroll"><table class="dense w-full"><thead><tr><th>时间</th><th>操作</th><th>状态</th><th>活动奖品</th><th>记录</th></tr></thead><tbody><tr v-for="(r,i) in history" :key="i"><td>{{new Date(r.at!).toLocaleString('zh-CN')}}</td><td>{{r.action==='drop_share'?'删转发':'取关'}}</td><td>{{({done:'已完成',running:'开始执行',unknown:'待核对',failed:'失败'} as Record<string,string>)[r.state!]||r.state}}</td><td>{{r.reward||'奖品待补全'}}</td><td>{{r.note}}</td></tr></tbody></table></div><footer><button :disabled="!historyPage" @click="showHistory(-1)">上一页</button><button :disabled="history.length<50" @click="showHistory(1)">下一页</button></footer></Modal>
 <Modal v-if="chosen" title="核对本人转发" @close="chosen=undefined"><p class="chosen-title">{{chosen.reward||'奖品待补全'}}</p><label v-for="(_,id) in chosen.choices" :key="id" class="link-choice"><input type="radio" v-model="selected" :value="id"/><a :href="'https://t.bilibili.com/'+id" target="_blank" rel="noreferrer">{{id}} ↗</a></label><button class="primary" :disabled="!!busy||!selected" @click="saveLink">确认对应活动奖品</button></Modal>
</div></template>
<style scoped>
.results-workspace{display:flex;flex-direction:column;gap:20px;max-width:1400px;margin:auto}.result-heading{padding:22px;display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.result-heading h2{font-size:18px;font-weight:650;margin-bottom:8px}.result-metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:14px}.result-metric{display:flex;flex-direction:column;align-items:flex-start;gap:10px;padding:18px;border-top:3px solid var(--line);height:auto}.result-metric strong{font-size:25px;font-variant-numeric:tabular-nums}.result-metric small{font-size:12px;font-weight:400}.result-pending{border-top-color:var(--discover)}.result-unknown{border-top-color:var(--warn)}.result-won{border-top-color:var(--accent)}.result-history{border-top-color:var(--editor)}.result-metric.selected{background:var(--accent-soft);outline:1px solid var(--accent)}.result-filters{display:flex;flex-direction:row;flex-wrap:wrap;align-items:center;gap:10px 16px;padding:16px;border-bottom:1px solid var(--line)}.result-filters input{width:190px;max-width:100%}.result-filters>form{flex:1;justify-content:flex-end}.result-filters .mini{min-height:32px;padding:5px 8px;font-size:12px}.result-filters select{width:108px}.table-scroll{overflow:auto}table{min-width:850px}th:first-child{width:auto}th:nth-child(4){width:180px}th:nth-child(2){width:110px}th:nth-child(3){width:145px}th:last-child{width:130px}td{vertical-align:middle;white-space:normal;text-align:center}td:first-child{text-align:left}td a{color:var(--discover);text-decoration:none}td small,.share-link{display:block;margin-top:6px;font-size:12px;color:var(--muted)}.evidence{max-width:180px;line-height:1.7;font-size:var(--text-meta)}.row-actions{display:flex;gap:10px;flex-direction:column;align-items:center}footer{display:flex;justify-content:flex-end;align-items:center;gap:14px;padding:18px;font-size:var(--text-meta)}.scan-status{font-size:12px}.link-choice{display:flex;gap:12px;margin:18px 0}.chosen-title{font-weight:600}@media(max-width:1100px){.result-metrics{grid-template-columns:repeat(3,minmax(0,1fr))}}
.evidence-text{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}td:first-child>a{font-weight:600;color:var(--text)}
.discard-table{min-width:0}.discard-table th:first-child{width:44%}.discard-table th:nth-child(2){width:auto}.discard-table th:last-child{width:112px}.discard-table td{white-space:normal;overflow-wrap:anywhere;overflow:visible;text-overflow:clip;line-height:1.7}
</style>
